// SPDX-License-Identifier: UNLICENSED

pragma solidity ^0.8.34 < 0.9.0;

abstract contract Auction {
    //เจ้าของการประมูล
    address payable public owner;
  //รายละเอียดสินค้า
    struct Product{
        string Brand;
        string SerialNumber;

    }
    //สถานะการประมูล
    enum AuctionState{ STARTED , ENDED, CANCELED }

    //งานในส่วนของผู้ใช้ client fuctions
    //ยื่นการประมูลโดยที่จะต้องมีการส่งเงินมาด้วย
    function bid() virtual external payable ; //external เสียค่า gas น้อยกว่า
    //ดูยอดเงินที่ประมูลของตัวเองละผู้อื่น 
    function getMyBid(address bidder) virtual external view returns(uint256);
    //owner fuctions 
    //จบการประมูลและยกเลิกการประมูล
    function endAuction() virtual external; 
    //ยกเลิกการประมูล
    function cancelAuction() virtual external;

    //sheared functions
    
    //ถอนเงิน
    function withdraw() virtual external; //รับเงินมี payable ถอนเงินจะไม่มี payable
    //ดูรายละเอียดสินค้า ดูproduct  มี view 
    function getProduct() virtual external view returns(string memory, string memory);

    //event
    //มีการประมูล
    event BidEvent(address bidder, uint256 amount , uint256 timestamp);
    //จบการประมูล
    event EndedEvent(string message, uint256 timestamp);
     //ยกเลิกการประมูล
    event CanceledEvent(string message, uint256 timestamp);
      //มีการถอนเงิน
    event WithdrawEvent(address withdrawer, uint256 amount, uint256 timestamp);
    
    
}

